input.content:
$repo = "C:\Users\ljtinitanao\Desktop\games\Official"
Set-Location $repo

# 1. Map deleted asset GUID -> asset path (from .meta at HEAD~1)
$deleted = git diff --name-only HEAD~1 HEAD | Where-Object { $_ -like "Assets/StarterAssets/*" }
$guidMap = @{}   # guid -> asset path (without .meta)
foreach ($f in $deleted) {
    if ($f.EndsWith(".meta")) {
        $content = git show "HEAD~1:$f" 2>$null
        if ($content -match '(?m)^\s*guid:\s*([0-9a-fA-F]{32})') {
            $guid = $matches[1]
            $asset = $f -replace '\.meta$',''
            $guidMap[$guid] = $asset
        }
    }
}
Write-Host "Deleted StarterAssets assets with guid: $($guidMap.Count)"

# 2. Build set of surviving game files to scan for references
$scanTypes = @("*.prefab","*.unity","*.mat","*.asset","*.controller","*.overrideController","*.anim","*.physicsmaterial","*.physicsmaterial2d","*.renderTexture")
$searchFiles = Get-ChildItem -LiteralPath Assets -Recurse -Include $scanTypes -File | Where-Object { $_.FullName -notlike "*StarterAssets*" } | ForEach-Object { $_.FullName }

# 3. Find used guids by scanning surviving files
$usedGuids = [System.Collections.Generic.HashSet[string]]::new()
foreach ($sf in $searchFiles) {
    $txt = Get-Content -LiteralPath $sf -Raw -ErrorAction SilentlyContinue
    if ($null -eq $txt) { continue }
    foreach ($m in [regex]::Matches($txt, 'guid:\s*([0-9a-fA-F]{32})')) {
        $g = $m.Groups[1].Value
        if ($guidMap.ContainsKey($g)) { $usedGuids.Add($g) | Out-Null }
    }
}
Write-Host "Directly referenced deleted assets: $($usedGuids.Count)"

# 4. Expand: restore textures/materials those assets depend on (BFS over deleted graph)
$queue = New-Object System.Collections.Queue
foreach ($g in $usedGuids) { $queue.Enqueue($g) }
while ($queue.Count -gt 0) {
    $g = $queue.Dequeue()
    $asset = $guidMap[$g]
    # read content of deleted asset (from HEAD~1)
    $content = git show "HEAD~1:$asset" 2>$null
    if ($null -eq $content) { continue }
    foreach ($m in [regex]::Matches($content, 'guid:\s*([0-9a-fA-F]{32})')) {
        $dep = $m.Groups[1].Value
        if ($guidMap.ContainsKey($dep) -and -not $usedGuids.Contains($dep)) {
            $usedGuids.Add($dep) | Out-Null
            $queue.Enqueue($dep)
        }
    }
}
Write-Host "Total deleted assets to restore (with deps): $($usedGuids.Count)"

# 5. Restore each (asset + its .meta) from HEAD~1
$restored = @()
foreach ($g in $usedGuids) {
    $asset = $guidMap[$g]
    git checkout HEAD~1 -- $asset 2>$null
    git checkout HEAD~1 -- "$asset.meta" 2>$null
    $restored += $asset
}
Write-Host "Restored files:"
$restored | Sort-Object | ForEach-Object { Write-Host "  $_" }

